package kr.workbench;
import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.net.*;import java.io.*;import java.util.*;import java.util.concurrent.atomic.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import burp.api.montoya.*;import burp.api.montoya.http.*;import burp.api.montoya.http.message.*;import burp.api.montoya.http.message.requests.HttpRequest;import burp.api.montoya.http.message.responses.HttpResponse;import burp.api.montoya.internal.*;
import kr.payloadrunner.*;
public class CommunityExtensionAudit extends WorkbenchTest {
 static int port,sends;static String base;static ObjectMapper mapper=new ObjectMapper();
 static List<Map<String,Object>> assertions=new ArrayList<>(),authRows=new ArrayList<>(),payloadRows=new ArrayList<>(),environmentRows=new ArrayList<>(),uiRows=new ArrayList<>(),gaps=new ArrayList<>();
 record Account(String name,String cookie,String csrf,String owner){}
 record Reply(int status,String headers,String body,byte[] raw){}
 static Account guest=new Account("guest","","","");
 static void verify(String name,boolean value){assertions.add(Map.of("test",name,"passed",value));System.out.println((value?"PASS ":"FAIL ")+name);if(!value)throw new AssertionError(name);}
 static byte[] send(byte[] raw)throws Exception{String first=new String(raw,StandardCharsets.ISO_8859_1).split("\r\n",2)[0];String path=first.split(" ")[1];if(!path.startsWith("/")||path.startsWith("//"))throw new IllegalArgumentException("local lab path only");sends++;try(Socket socket=new Socket()){socket.connect(new InetSocketAddress("127.0.0.1",port),3000);socket.setSoTimeout(10000);socket.getOutputStream().write(raw);return socket.getInputStream().readAllBytes();}}
 static Reply reply(byte[] raw)throws IOException{var r=Engine.parse(raw);return new Reply(r.status(),new String(raw,StandardCharsets.ISO_8859_1).split("\r\n\r\n",2)[0],r.text(),raw);}
 static String template(String method,String path,Account a,String body,String type){return method+" "+path+" HTTP/1.1\r\nHost: 127.0.0.1:"+port+"\r\nConnection: close\r\n"+(a.cookie.isEmpty()?"":"Cookie: "+a.cookie+"\r\n")+(a.csrf.isEmpty()?"":"X-CSRF-Token: "+a.csrf+"\r\n")+(type.isEmpty()?"":"Content-Type: "+type+"\r\n")+(body.isEmpty()?"":"Content-Length: "+body.getBytes(StandardCharsets.UTF_8).length+"\r\n")+"\r\n"+body;}
 static Reply get(String path,Account a)throws Exception{return reply(send(template("GET",path,a,"","").getBytes(StandardCharsets.UTF_8)));}
 static Reply post(String path,Account a,String body,String type)throws Exception{return reply(send(template("POST",path,a,body,type).getBytes(StandardCharsets.UTF_8)));}
 static Account login(String name,String owner)throws Exception{Reply r=post("/api/auth/login",guest,"username="+name+"&password=LabOnly%212026","application/x-www-form-urlencoded");verify("live login "+name,r.status==200);String cookie=EnvironmentResponse.header(r.headers,"Set-Cookie").split(";",2)[0];Map<?,?> doc=mapper.readValue(r.body,Map.class);return new Account(name,cookie,doc.get("csrf").toString(),owner);}
 static HttpRequest q(String path,String method,Account a,String body,String type){List<HttpHeader> hs=new ArrayList<>();if(!a.cookie.isEmpty())hs.add(header("Cookie",a.cookie));if(!a.csrf.isEmpty())hs.add(header("X-CSRF-Token",a.csrf));if(!type.isEmpty())hs.add(header("Content-Type",type));return requestAdapter(base+path,method,body,hs);}
 static HttpRequest requestAdapter(String url,String method,String body,List<HttpHeader> hs){HttpRequest fallback=request(url,method,true,hs);return proxy(HttpRequest.class,(p,m,a)->switch(m.getName()){
  case "bodyToString"->body;case "body"->bytes(body.getBytes(StandardCharsets.UTF_8));
  case "toByteArray"->bytes(wire(url,method,body,hs));case "toString"->new String(wire(url,method,body,hs),StandardCharsets.UTF_8);
  case "withRemovedHeader"->{List<HttpHeader> n=new ArrayList<>(hs);if(a[0] instanceof HttpHeader)n.remove(a[0]);else n.removeIf(x->x.name().equalsIgnoreCase((String)a[0]));yield requestAdapter(url,method,body,n);}
  case "withHeader"->{List<HttpHeader> n=new ArrayList<>(hs);n.removeIf(x->x.name().equalsIgnoreCase((String)a[0]));n.add(header((String)a[0],(String)a[1]));yield requestAdapter(url,method,body,n);}
  default->m.invoke(fallback,a);
 });}
 static byte[] wire(String url,String method,String body,List<HttpHeader> hs){URI u=URI.create(url);if(!u.getHost().equals("127.0.0.1")||u.getPort()!=port)throw new IllegalArgumentException("scope");String text=method+" "+u.getRawPath()+(u.getRawQuery()==null?"":"?"+u.getRawQuery())+" HTTP/1.1\r\nHost: 127.0.0.1:"+port+"\r\nConnection: close\r\n";for(var h:hs)text+=h.name()+": "+h.value()+"\r\n";if(!body.isEmpty())text+="Content-Length: "+body.getBytes(StandardCharsets.UTF_8).length+"\r\n";return (text+"\r\n"+body).getBytes(StandardCharsets.UTF_8);}
 static HttpResponse responseAdapter(Reply r){HttpResponse fallback=response(r.status,r.body);List<HttpHeader> hs=new ArrayList<>();for(String line:r.headers.split("\r\n")){int i=line.indexOf(':');if(i>0)hs.add(header(line.substring(0,i),line.substring(i+1).strip()));}return proxy(HttpResponse.class,(p,m,a)->switch(m.getName()){case "toByteArray"->bytes(r.raw);case "headers"->hs;case "headerValue"->EnvironmentResponse.header(r.headers,a[0].toString());case "toString"->r.headers+"\r\n\r\n"+r.body;default->m.invoke(fallback,a);});}
 static String classify(String id,String path,Account baseline,Account target,String ownerPath,String expected)throws Exception{Reply a=get(path,baseline),b=get(path,target);var result=AuthJudgement.compare(a.status,a.body,b.status,b.body,AuthJudgement.rules("","error=FORBIDDEN\nerror=UNAUTHORIZED",ownerPath),expected);authRows.add(Map.of("id",id,"path",path,"baselineAccount",baseline.name,"account",target.name,"baselineStatus",a.status,"status",b.status,"state",result.state(),"reason",result.reason()));return result.state();}
 static List<Engine.Row> scan(String id,Engine.Profile profile,String template,String original,List<String> payloads,String proof,boolean adaptive)throws Exception{List<Engine.Row> rows=new ArrayList<>();Engine.Config config=new Engine.Config(profile,Engine.Encoding.URL,template,original,payloads,0,25,proof);Object summary=adaptive?Adaptive.run(config,CommunityExtensionAudit::send,new AtomicBoolean(),rows::add):Engine.run(config,CommunityExtensionAudit::send,new AtomicBoolean(),rows::add);Map<String,Object> data=new LinkedHashMap<>();data.put("id",id);data.put("profile",profile.toString());data.put("adaptive",adaptive);data.put("summary",summary);data.put("rows",rows.stream().map(r->Map.of("payload",r.payload(),"status",r.response()==null?0:r.response().status(),"verdict",r.verdict(),"evidence",r.evidence(),"bodyChars",r.response()==null?0:r.response().text().length(),"bodySha256",r.response()==null?"":Core.hash(r.response().text().getBytes(StandardCharsets.UTF_8)))).toList());payloadRows.add(data);return rows;}
 static boolean candidate(List<Engine.Row> rows,String needle){return rows.stream().anyMatch(r->r.verdict().contains(needle));}
 static void uiCompare(MontoyaApi api,String id,HttpRequest original,Reply baseline,Account target,boolean writes,String ownerPath,String owner)throws Exception{
  AtomicReference<AuthComparePanel> box=new AtomicReference<>();edt(()->box.set(new AuthComparePanel(api,()->List.of(AuthRecordTest.rr(original,responseAdapter(baseline))))));var panel=box.get();
  edt(()->{panel.observe(q("/api/auth/me","GET",target,"",""),response(200,"{}"));panel.assign(0,panel.credentials.values().iterator().next());panel.profileNames[0].setText(target.name);panel.ownerPath.setText(ownerPath);panel.profileOwners[0].setText(owner);panel.writes.setSelected(writes);panel.compareSelection();});AuthRecordTest.idle(panel);
  var packet=panel.runs.get(0).packets[0];uiRows.add(Map.of("id",id,"status",packet.response==null?0:(int)packet.response.statusCode(),"note",packet.note,"csrfReplaced",packet.request.headers().stream().anyMatch(h->h.name().equalsIgnoreCase("X-CSRF-Token")&&h.value().equals(target.csrf))));
  verify("live AuthComparePanel response "+id,packet.response!=null);if(writes)verify("target CSRF replaced on actual write replay",packet.request.headers().stream().anyMatch(h->h.name().equalsIgnoreCase("X-CSRF-Token")&&h.value().equals(target.csrf)));
  edt(panel::close);
 }
 public static void main(String[] args)throws Exception{
  port=Integer.parseInt(args[0]);base="http://127.0.0.1:"+port;Path report=Path.of(args[1]);Map<String,Object> result=new LinkedHashMap<>();
  try{
   verify("live Spring Tomcat H2 lab healthy",get("/health",guest).status==200);
   Account alice=login("alice","1"),bob=login("bob","2"),admin=login("admin","3"),moder=login("moderator","4");
   for(String mode:List.of("vuln","fixed")){
    String p="/api/community/"+mode;
    verify(mode+" private post classification",classify(mode+"-private-post",p+"/posts/102",bob,alice,"$.OWNER_ID","1").equals(mode.equals("vuln")?"타인 객체 접근 의심":"판정 보류"));
    verify(mode+" private note classification",classify(mode+"-private-message",p+"/messages/202",bob,alice,"$.SENDER_ID","1").equals(mode.equals("vuln")?"타인 객체 접근 의심":"판정 보류"));
    verify(mode+" private attachment classification",classify(mode+"-private-file",p+"/files/bob-private-file",bob,alice,"","").equals(mode.equals("vuln")?"우회 의심":"판정 보류"));
    verify(mode+" admin spoof classification",classify(mode+"-admin",p+"/admin/users?role=ADMIN",admin,alice,"","").equals(mode.equals("vuln")?"우회 의심":"차단 근거 확인"));
    verify(mode+" public page yields generic suspicion",classify(mode+"-public",p+"/posts/101",alice,guest,"","").equals("우회 의심"));
    verify(mode+" own owner rule mislabels public object",classify(mode+"-public-owner-rule",p+"/posts/101",alice,bob,"$.OWNER_ID","2").equals("타인 객체 접근 의심"));
    classify(mode+"-members-guest",p+"/posts/103",alice,guest,"","");
    classify(mode+"-moderator-private",p+"/posts/104",alice,moder,"$.OWNER_ID","4");
    for(boolean adaptive:List.of(false,true)){
     var sql=scan(mode+"-sql-error",Engine.Profile.SQLI,template("GET",p+"/search?q=§PAYLOAD§",alice,"",""),"Burp",List.of("'"),"",adaptive);verify(mode+" SQL error "+adaptive,candidate(sql,"SQL 오류 후보")==mode.equals("vuln"));
     var differential=scan(mode+"-sql-boolean",Engine.Profile.SQLI,template("GET",p+"/search?q=§PAYLOAD§",alice,"",""),"Burp",List.of("{{BASE}}%' AND 1=1 -- ","{{BASE}}%' AND 1=2 -- "),"",adaptive);
     boolean booleanFound=candidate(differential,"SQL 조건 차이");if(mode.equals("vuln")&&!booleanFound)gaps.add(Map.of("id","SQL-BOOLEAN-NORMALIZATION","adaptive",adaptive,"observed","Stable true response same as baseline, false response differs, but no SQL condition candidate"));
     verify(mode+" boolean probes return HTTP responses "+adaptive,differential.stream().allMatch(r->r.response()!=null));if(mode.equals("fixed"))verify("fixed boolean no SQL condition candidate "+adaptive,!booleanFound);
     if(mode.equals("vuln")){var baseline=differential.get(0).response();var truth=differential.stream().filter(r->r.payload().contains("1=1")).findFirst().orElseThrow().response();var falsehood=differential.stream().filter(r->r.payload().contains("1=2")).findFirst().orElseThrow().response();verify("SQL boolean baseline equals true and differs from false "+adaptive,baseline.text().equals(truth.text())&&!baseline.text().equals(falsehood.text()));}
     var xss=scan(mode+"-xss",Engine.Profile.XSS,template("GET","/"+mode+"/preview?text=§PAYLOAD§",alice,"",""),"hello",List.of("<img src=x onerror=console.log('{{MARKER}}')>"),"",adaptive);verify(mode+" reflected XSS "+adaptive,candidate(xss,"XSS 반사 후보")==mode.equals("vuln"));
     var file=scan(mode+"-file",Engine.Profile.DOWNLOAD,template("GET",p+"/files/§PAYLOAD§",alice,"",""),"missing-training-file",List.of("bob-private-file"),"BOB_PRIVATE_ATTACHMENT",adaptive);verify(mode+" file evidence "+adaptive,candidate(file,"지정 파일 내용 발견")==mode.equals("vuln"));
    }
   }
   // Actual asynchronous panel code, with API adapters translating every replay into a real local HTTP request.
   ObjectFactoryLocator.FACTORY=proxy(MontoyaObjectFactory.class,(p,m,a)->m.getName().equals("requestOptions")?proxy(RequestOptions.class,(pp,mm,aa)->pp):def(m));
   var http=proxy(burp.api.montoya.http.Http.class,(p,m,a)->{if(!m.getName().equals("sendRequest"))return def(m);HttpRequest request=(HttpRequest)a[0];Reply rr=reply(send(request.toByteArray().getBytes()));return AuthRecordTest.rr(request,responseAdapter(rr));});
   MontoyaApi api=proxy(MontoyaApi.class,(p,m,a)->switch(m.getName()){case "http"->http;case "scope"->proxy(burp.api.montoya.scope.Scope.class,(pp,mm,aa)->mm.getName().equals("isInScope")?aa[0].toString().startsWith(base+"/"):def(mm));default->def(m);});
   uiCompare(api,"vulnerable-private",q("/api/community/vuln/posts/102","GET",bob,"",""),get("/api/community/vuln/posts/102",bob),alice,false,"$.OWNER_ID","1");
   uiCompare(api,"fixed-private",q("/api/community/fixed/posts/102","GET",bob,"",""),get("/api/community/fixed/posts/102",bob),alice,false,"$.OWNER_ID","1");
   uiCompare(api,"fixed-public",q("/api/community/fixed/posts/101","GET",alice,"",""),get("/api/community/fixed/posts/101",alice),bob,false,"$.OWNER_ID","2");
   Reply created=post("/api/community/fixed/posts",alice,"title=audit&body=LOCAL_AUDIT&visibility=PRIVATE&category=general","application/x-www-form-urlencoded");verify("isolated training post created",created.status==200);String pid=mapper.readValue(created.body,Map.class).get("id").toString();
   String body="title=audit&body=LOCAL_AUDIT&visibility=PRIVATE&category=general",edit="/api/community/fixed/posts/"+pid+"/edit";Reply ownEdit=post(edit,alice,body,"application/x-www-form-urlencoded");
   uiCompare(api,"fixed-write-real-csrf",q(edit,"POST",alice,body,"application/x-www-form-urlencoded"),ownEdit,bob,true,"$.OWNER_ID","2");
   for(String mode:List.of("vuln","fixed")){
    String upload="/api/community/"+mode+"/posts/101/files?name=§PAYLOAD§";
    var rows=scan(mode+"-upload-name",Engine.Profile.UPLOAD_NAME,template("POST",upload,alice,"training-only","text/plain"),"baseline.txt",List.of("probe.html"),"",false);verify(mode+" upload acceptance",candidate(rows,"업로드 수락 후보")==mode.equals("vuln"));
   }
   // Stored XSS remains JSON at the API boundary; frontend sink is reviewed separately, no browser execution claim.
   var stored=scan("stored-comment-json",Engine.Profile.XSS,template("POST","/api/community/vuln/posts/101/comments",alice,"body=§PAYLOAD§","application/x-www-form-urlencoded"),"baseline-audit",List.of("<img src=x onerror=console.log('{{MARKER}}')>"),"",false);
   Reply comments=get("/api/community/vuln/posts/101",alice);verify("stored marker returned by separate GET",comments.body.contains("onerror=console.log"));verify("JSON storage success has no reflected HTML XSS verdict",!candidate(stored,"XSS 반사 후보"));
   var jwt=get("/api/extensions/jwt/issue",alice);verify("live JWT issued",jwt.status==200);String token=mapper.readValue(jwt.body,Map.class).get("token").toString();String decoded=Core.jwt(token);result.put("jwt",decoded);verify("JWT UTC time displayed",decoded.contains("UTC")||decoded.contains("Z"));
   // Real absent controls and exposed/protected configuration responses.
   String missing1="/audit-missing-one",missing2="/audit-missing-two";Reply m1=get(missing1,guest),m2=get(missing2,guest);var ref=EnvironmentControls.reference(EnvironmentControls.sample(m1.status,m1.headers,m1.body,base+missing1,Set.of()),EnvironmentControls.sample(m2.status,m2.headers,m2.body,base+missing2,Set.of()),true,"");result.put("missingPathControls",Map.of("firstBody",m1.body,"secondBody",m2.body,"first",EnvironmentControls.sample(m1.status,m1.headers,m1.body,base+missing1,Set.of()),"second",EnvironmentControls.sample(m2.status,m2.headers,m2.body,base+missing2,Set.of()),"reference",ref));
   for(String path:List.of("/.env","/.git/config","/api/vuln/config","/api/fixed/config","/v3/api-docs")){Reply r=get(path,guest);String state=EnvironmentControls.state(r.status,r.headers,r.body,base+path,ref,Set.of());environmentRows.add(Map.of("path",path,"status",r.status,"state",state));verify("environment no automatic vulnerability verdict "+path,!state.contains("취약"));}
   Reply js=get("/assets/community.js",guest);var analysis=JsAnalysis.analyze(js.body,base+"/assets/community.js");result.put("communityJs",analysis);verify("community JS retrieved and analyzed",js.status==200&&!analysis.truncated());
   var discovery=ReconMetadata.discover(base+"/assets/community.js",js.body,true);result.put("communityJsDiscoveries",discovery);
   Path fixtures=report.getParent().resolve("http-js-fixtures");Files.createDirectories(fixtures);List<Map<String,Object>> fixtureReports=new ArrayList<>();
   for(String filename:List.of("01-fetch.js","02-axios.js","03-xhr-navigation.js","04-constants.js","05-dynamic-scope.js","06-secrets.js","07-negative.js","08-modern-module.js","09-invalid.js","10-recon.js","11-sourcemap.js","12-inline-map.js","13-inline.html","14-package.json","11-sourcemap.js.map")){Reply fixture=get("/assets/js-lab/"+filename,guest);verify("live JS fixture "+filename,fixture.status==200);Files.writeString(fixtures.resolve(filename),fixture.body);fixtureReports.add(Map.of("file",filename,"result",JsAnalysis.analyze(fixture.body,base+"/assets/js-lab/"+filename)));}result.put("jsFixtures",fixtureReports);
   result.put("openapiDiscoveryCount",ReconMetadata.discover(base+"/v3/api-docs",get("/v3/api-docs",guest).body,false).size());
   List<String> samePattern=List.of(base+"/api/community/fixed/posts/101",base+"/api/community/fixed/posts/102");var groups=UrlGroups.groups(samePattern,Set.of());result.put("representativeExample",groups);verify("public and private objects grouped together",groups.size()==1&&groups.get(0).urls().size()==2);verify("same pattern has different guest access policy",get("/api/community/fixed/posts/101",guest).status==200&&get("/api/community/fixed/posts/102",guest).status==404);
   result.put("pathCategories",Map.of("privatePost",ReconMetadata.category(samePattern.get(1)),"privateMessage",ReconMetadata.category(base+"/api/community/fixed/messages/202"),"file",ReconMetadata.category(base+"/api/community/fixed/files/bob-private-file")));
   ActivityTracker tracker=new ActivityTracker();tracker.discover(new ReconMetadata.Discovery(base+"/api/community/vuln/posts","GET",Set.of("lab_hidden"),Set.of(),"JS"));tracker.observe(q("/api/community/vuln/posts?lab_hidden=first","GET",alice,"",""),"PROXY");tracker.observe(q("/api/community/vuln/posts?lab_hidden=second","GET",alice,"",""),"REPEATER");verify("activity query mutation recorded",tracker.views().get(0).parameters().stream().anyMatch(p->p.key().equals("URL:lab_hidden")&&p.state().equals("변경 관찰")));verify("activity does not auto-complete vulnerability check",!tracker.views().get(0).state().equals("점검 완료"));result.put("activity",tracker.views());
   tracker.review("GET",base+"/api/community/fixed/posts/101","bob: 공개 객체 소유값 불일치 후보");verify("public auth candidate enters review queue",tracker.views().stream().anyMatch(v->v.url().endsWith("/101")&&v.state().equals("재검토 필요")));
   Reply reflected=get("/api/community/vuln/posts?lab_hidden=AUDIT_MARKER",alice),safe=get("/api/community/fixed/posts?lab_hidden=AUDIT_MARKER",alice);verify("actual hidden query vulnerable/fixed split",reflected.body.contains("LOOP_QUERY=AUDIT_MARKER")&&!safe.body.contains("AUDIT_MARKER"));
  }finally{
   result.put("version","0.17.4");result.put("site","LOOP Community Lab 3.3 source, embedded Spring/Tomcat/H2");result.put("mode","actual loopback HTTP + production extension JAR; API adapters and headless Swing; no actual Burp GUI");result.put("httpRequests",sends);result.put("checks",assertions);result.put("passed",assertions.stream().filter(x->Boolean.TRUE.equals(x.get("passed"))).count());result.put("failed",assertions.stream().filter(x->Boolean.FALSE.equals(x.get("passed"))).count());result.put("auth",authRows);result.put("payload",payloadRows);result.put("authPanel",uiRows);result.put("environment",environmentRows);result.put("gaps",gaps);mapper.writerWithDefaultPrettyPrinter().writeValue(report.toFile(),result);
  }
  System.out.println("AUDIT_SUMMARY checks="+assertions.size()+" HTTP_requests="+sends);
 }
}
